// ── EDIT THESE ──
const CONFIG = {
  LEADS_API_URL: 'https://CLINIC-API/leads',          // endpoint that LISTS leads (with status)
  LEADS_API_AUTH_HEADER: 'Authorization',
  LEADS_API_AUTH_VALUE: 'Bearer YOUR-CLINIC-TOKEN',
  SUPABASE_URL: 'https://YOUR-PROJECT.supabase.co',
  SUPABASE_ANON_KEY: 'sb_publishable_...',          // Publishable key (or legacy anon key)
  INGEST_SECRET: 'YOUR-INGEST-SECRET',               // select value from ha_settings where key = 'ingest_secret';
  DAYS_BACK: 7                                       // re-sync leads created in the last N days (status changes)
};
const since = new Date(Date.now() - CONFIG.DAYS_BACK * 86400000).toISOString().slice(0, 10);
return [{ json: { ...CONFIG, since } }];

// Turns the clinic API response into ha_leads rows.
// If the clinic API uses other field names, change the pick(...) lists below.
const cfg = $('Config').first().json;
const res = $input.first().json;
const list = Array.isArray(res) ? res
  : (res.data || res.leads || res.results || res.items || []);
// n8n splits a top-level array into items — handle that too
const raw = list.length ? list : $input.all().map(i => i.json);

const pick = (o, keys) => { for (const k of keys) { const v = k.split('.').reduce((a, p) => a == null ? a : a[p], o); if (v !== undefined && v !== null && v !== '') return v; } return null; };
const STATUS = { 'new':'new', 'جديد':'new', 'contacted':'contacted', 'تم التواصل':'contacted', 'qualified':'qualified', 'مهتم':'qualified',
  'booked':'booked', 'حجز':'booked', 'appointment':'booked', 'showed':'showed', 'attended':'showed', 'حضر':'showed',
  'paid':'paid', 'done':'paid', 'completed':'paid', 'تم':'paid', 'lost':'lost', 'cancelled':'lost', 'not interested':'lost' };

const rows = raw.map(l => {
  const s = String(pick(l, ['status', 'stage', 'lead_status', 'state']) || 'new').toLowerCase().trim();
  return {
    lead_id: String(pick(l, ['id', 'lead_id', '_id', 'uuid'])),
    created_at: pick(l, ['created_at', 'createdAt', 'date', 'created']),
    name: pick(l, ['name', 'client_name', 'full_name', 'patient_name']),
    phone: pick(l, ['phone', 'mobile', 'phone_number', 'client_phone']),
    service: pick(l, ['service', 'interest', 'service_name', 'treatment']),
    branch: pick(l, ['branch', 'branch_name', 'location']),
    channel: pick(l, ['channel', 'source_channel', 'via']),
    source: pick(l, ['source', 'lead_source']),
    utm_source: pick(l, ['utm_source', 'utm.source']),
    utm_medium: pick(l, ['utm_medium', 'utm.medium']),
    utm_campaign: pick(l, ['utm_campaign', 'utm.campaign']),
    utm_term: pick(l, ['utm_term', 'utm.term']),
    gclid: pick(l, ['gclid', 'google_click_id']),
    ref: pick(l, ['ref']),
    status: STATUS[s] || s,
    value: pick(l, ['value', 'amount', 'price', 'total', 'paid_amount']),
    raw: l
  };
}).filter(r => r.lead_id && r.lead_id !== 'null');

return [{ json: {
  url: cfg.SUPABASE_URL + '/rest/v1/rpc/ha_ingest_leads',
  key: cfg.SUPABASE_ANON_KEY,
  body: { payload: { secret: cfg.INGEST_SECRET, rows } },
  count: rows.length
} }];
